      T.push(`${++n}. ${fr.name}(${u.names.join(', ')}) — ${st}`, ...(fr.cond ? [`기준: ${fr.cond}`] : []), fr.note, `근거: ${fr.basis.map(lawText).join(', ')}`, ...R(fr.rulings).map(r => `- ${r.kind} ${r.no} ${r.title}: ${r.gist}${r.verify ? ' (원문 확인 필요)' : ''}`), '');
