      const q = (D.inquiries ?? []).find(x => x.fac === type); if (q && fr.status === 'check') { facParts.push(inquiryHtml(D, q, { ...ctx, facilities: u.names.join(', ') })); inqs.push({ key: q.key, text: inquiryText(D, q, { ...ctx, facilities: u.names.join(', ') }) }); }
